// ── Version + update handlers (unified update service) ─────────────────────────

/// `GET /api/version` — the installed Ryu version + per-component builds.
#[utoipa::path(
    get,
    path = "/api/version",
    tag = "Health",
    summary = "Installed version and per-component builds",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_version() -> Json<crate::update::VersionInfo> {
    // The Gateway is the one component Core can actually observe — its version is
    // cached by the readiness probe, so this stays a pure read. Before this, every
    // component was stamped with Core's own version and a stale Gateway reported
    // itself as current.
    Json(crate::update::version_info_with(
        crate::sidecar::gateway::observed_gateway_version().as_deref(),
    ))
}

/// Query for `GET /api/update/check`.
#[derive(serde::Deserialize, Default)]
struct UpdateCheckQuery {
    /// Release channel to check (`stable` / `beta` / `nightly` / `canary`).
    ///
    /// Omitted means "the channel this build is already on", derived from the
    /// running version itself — so a nightly Core checks nightly with no stored
    /// preference. The desktop passes its user-chosen channel explicitly so the
    /// channel picker can move a user between channels.
    channel: Option<String>,
    /// RFC-3339 instant limiting the verdict to releases published at or before
    /// it — the caller's lifetime updates window. Omitted (the normal case, and
    /// every non-lifetime caller) means unclamped, byte-identical to the
    /// historical behaviour.
    ///
    /// ADVISORY ONLY. This route is on the UNAUTHENTICATED public router, so the
    /// value is caller-supplied and trivially omitted. Core declines to OFFER a
    /// build; it cannot prevent one. The perpetual desktop licence is an honour
    /// system by design.
    ///
    /// PRIVACY NOTE: this is a per-user, purchase-derived timestamp travelling in
    /// a URL query string. Core has no TraceLayer so it does not access-log URIs,
    /// but a node reached over the network sits behind a proxy that does.
    updates_until: Option<String>,
}

/// The 200 body [`update_check`] answers with when the check itself failed.
///
/// A SECOND, hand-built copy of the [`crate::update::UpdateCheck`] wire shape —
/// the `error` key exists only here, so the struct cannot be reused — which makes
/// it the one place the two definitions can silently drift. It is a named
/// function purely so `update_check_fail_open_matches_the_verdict_shape` can hold
/// the two key sets against each other.
///
/// `restricted_by_cutoff` and `cutoff_unresolved` are deliberately FALSE: this
/// arm means "GitHub is unreachable", and a client must never read a network
/// failure as an expired updates window.
fn update_check_fail_open_body(current: &str, channel: &str, error: &str) -> serde_json::Value {
    json!({
        "current": current,
        "latest": current,
        "channel": channel,
        "update_available": false,
        "notes": serde_json::Value::Null,
        "html_url": serde_json::Value::Null,
        "asset": serde_json::Value::Null,
        "tag": serde_json::Value::Null,
        "published_at": serde_json::Value::Null,
        "latest_unrestricted": current,
        "restricted_by_cutoff": false,
        "cutoff_waived_for_security": false,
        "cutoff_unresolved": false,
        "error": error,
    })
}

/// `GET /api/update/check` — compares the installed version against the latest
/// release ON ITS CHANNEL. Fails open: a network/API error returns 200 with
/// `update_available: false` so a client never blocks launch on a flaky check.
#[utoipa::path(
    get,
    path = "/api/update/check",
    tag = "Health",
    summary = "Compare installed version against the latest release on its channel",
    params(
        ("channel" = Option<String>, Query, description = "stable | beta | nightly | canary"),
        (
            "updates_until" = Option<String>,
            Query,
            description = "RFC-3339 cutoff; clamp to releases published at or before it (lifetime updates window)"
        )
    ),
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn update_check(
    State(state): State<ServerState>,
    Query(query): Query<UpdateCheckQuery>,
) -> axum::response::Response {
    let requested = query
        .channel
        .as_deref()
        .map(str::trim)
        .filter(|c| !c.is_empty());
    let requested_cutoff = query
        .updates_until
        .as_deref()
        .map(str::trim)
        .filter(|c| !c.is_empty());
    match crate::update::check_for_update_with(
        &state.client,
        crate::update::UpdateCheckOptions {
            channel: requested,
            updates_until: requested_cutoff,
        },
    )
    .await
    {
        Ok(verdict) => (StatusCode::OK, Json(json!(verdict))).into_response(),
        Err(e) => {
            tracing::warn!("update check failed (treating as up-to-date): {e}");
            let current = crate::update::current_version();
            let channel = requested
                .map(str::to_string)
                .unwrap_or_else(|| crate::update::channel_of(&current));
            (
                StatusCode::OK,
                Json(update_check_fail_open_body(
                    &current,
                    &channel,
                    &e.to_string(),
                )),
            )
                .into_response()
        }
    }
}

#[cfg(test)]
mod update_check_wire_shape_tests {
    use super::update_check_fail_open_body;

    /// The fail-open arm must answer with the SAME keys a successful verdict does,
    /// plus `error`. A client that reads a new field would otherwise see it simply
    /// missing when GitHub is unreachable — and for `restricted_by_cutoff` that
    /// silence is indistinguishable from "your updates window lapsed".
    #[test]
    fn update_check_fail_open_matches_the_verdict_shape() {
        let verdict = crate::update::UpdateCheck {
            current: "1.0.0".to_string(),
            latest: "1.0.0".to_string(),
            channel: "stable".to_string(),
            update_available: false,
            notes: None,
            html_url: None,
            asset: None,
            tag: None,
            published_at: None,
            latest_unrestricted: "1.0.0".to_string(),
            restricted_by_cutoff: false,
            cutoff_waived_for_security: false,
            cutoff_unresolved: false,
        };
        let mut expected: Vec<String> = serde_json::to_value(&verdict)
            .unwrap()
            .as_object()
            .unwrap()
            .keys()
            .cloned()
            .collect();
        expected.push("error".to_string());
        expected.sort();

        let body = update_check_fail_open_body("1.0.0", "stable", "boom");
        let mut actual: Vec<String> = body.as_object().unwrap().keys().cloned().collect();
        actual.sort();

        assert_eq!(actual, expected);
    }

    /// A network failure is NOT a lapsed updates window: both cutoff flags stay
    /// false here so the desktop never shows an "updates expired" state because
    /// GitHub was down.
    #[test]
    fn update_check_fail_open_never_reports_a_cutoff() {
        let body = update_check_fail_open_body("1.0.0", "stable", "boom");
        assert_eq!(body["restricted_by_cutoff"], serde_json::Value::Bool(false));
        assert_eq!(body["cutoff_unresolved"], serde_json::Value::Bool(false));
        assert_eq!(
            body["cutoff_waived_for_security"],
            serde_json::Value::Bool(false)
        );
        assert_eq!(body["latest_unrestricted"], body["current"]);
    }
}

/// `POST /api/update/schedule` — install this update at the node's next quiet
/// hour instead of now.
///
/// The asset is PINNED from the request body, not re-resolved when the window
/// arrives: installing "whatever is latest at 03:00" would put a version the
/// user never saw onto a machine they deliberately chose not to touch during
/// the day.
#[utoipa::path(
    post,
    path = "/api/update/schedule",
    tag = "Health",
    summary = "Defer an update to the node's next quiet hour",
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn schedule_update(Json(body): Json<serde_json::Value>) -> axum::response::Response {
    let asset: crate::update::ReleaseAsset =
        match serde_json::from_value(body.get("asset").cloned().unwrap_or(body.clone())) {
            Ok(a) => a,
            Err(e) => {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({ "error": format!("invalid asset: {e}") })),
                )
                    .into_response();
            }
        };
    let version = body
        .get("version")
        .and_then(|v| v.as_str())
        .unwrap_or_default()
        .to_string();
    match crate::update::schedule::set_pending(asset, version) {
        Ok(pending) => (StatusCode::OK, Json(json!(pending))).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": e.to_string() })),
        )
            .into_response(),
    }
}

/// `GET /api/update/schedule` — the deferred update, if any.
///
/// Also reports the node's zone so a client can say WHEN without guessing: the
/// viewer's zone is usually not the node's, and "03:00" with no zone is exactly
/// the ambiguity deferring is supposed to remove.
#[utoipa::path(
    get,
    path = "/api/update/schedule",
    tag = "Health",
    summary = "The deferred update, if one is pending",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_update_schedule() -> axum::response::Response {
    let pending = crate::update::schedule::get_pending();
    (
        StatusCode::OK,
        Json(json!({
            "pending": pending,
            "timeZone": crate::update::schedule::local_timezone(),
        })),
    )
        .into_response()
}

/// `DELETE /api/update/schedule` — forget the deferred update.
#[utoipa::path(
    delete,
    path = "/api/update/schedule",
    tag = "Health",
    summary = "Cancel a deferred update",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn cancel_update_schedule() -> axum::response::Response {
    match crate::update::schedule::clear_pending() {
        Ok(()) => (StatusCode::OK, Json(json!({ "ok": true }))).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": e.to_string() })),
        )
            .into_response(),
    }
}

/// `POST /api/update/apply` — download + install an update for the headless
/// binaries. Body is the [`crate::update::ReleaseAsset`] returned by the check.
#[utoipa::path(
    post,
    path = "/api/update/apply",
    tag = "Health",
    summary = "Download and apply an update (headless binaries)",
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn update_apply(
    State(state): State<ServerState>,
    Json(asset): Json<crate::update::ReleaseAsset>,
) -> axum::response::Response {
    match crate::update::apply::apply_update(&state.downloads, &asset).await {
        Ok(result) => (StatusCode::OK, Json(json!(result))).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": e.to_string() })),
        )
            .into_response(),
    }
}

// ── Preferences handlers (cross-surface theme sync) ────────────────────────────

#[utoipa::path(
    get,
    path = "/api/preferences/{key}",
    tag = "Preferences",
    summary = "Get a preference value",
    params(("key" = String, Path)),
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_preference(
    State(state): State<ServerState>,
    Path(key): Path<String>,
) -> axum::response::Response {
    // The node-wide default selection has a built-in value (flagship agent on the
    // bundled local Gemma), served HERE rather than seeded into the store: every
    // client — the composer's seed chain, the Defaults dialog, plugins — reads the
    // preference through this one route, so a read-default reaches all of them
    // while still letting a cleared preference genuinely return to the default.
    let default_value = |key: &str| -> Option<String> {
        matches!(
            key,
            crate::agent_selection::GLOBAL_SELECTION_PREF
                | crate::agent_selection::LOCAL_SELECTION_PREF
        )
        .then(|| serde_json::to_string(&crate::agent_selection::builtin_default_selection()).ok())
        .flatten()
    };
    match state.preferences.get(&key).await {
        Ok(Some(value)) if value.trim().is_empty() => {
            let value = default_value(&key)
                .map(serde_json::Value::String)
                .unwrap_or(serde_json::Value::Null);
            (StatusCode::OK, Json(json!({ "key": key, "value": value }))).into_response()
        }
        Ok(Some(value)) => {
            (StatusCode::OK, Json(json!({ "key": key, "value": value }))).into_response()
        }
        // An unset key is not an error for a KV store. The local lane is the one
        // compatibility exception: when its new key is absent, read the former
        // single default so old installations migrate without a write.
        Ok(None) if key == crate::agent_selection::LOCAL_SELECTION_PREF => {
            let value = crate::agent_selection::load_local(&state.preferences).await;
            let value = serde_json::to_string(&value)
                .map(serde_json::Value::String)
                .unwrap_or(serde_json::Value::Null);
            (StatusCode::OK, Json(json!({ "key": key, "value": value }))).into_response()
        }
        // An unset key is not an error for a KV store: return 200 with a null
        // value so clients reading optional prefs don't generate console 404 noise.
        Ok(None) => {
            let value = default_value(&key)
                .map(serde_json::Value::String)
                .unwrap_or(serde_json::Value::Null);
            (StatusCode::OK, Json(json!({ "key": key, "value": value }))).into_response()
        }
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": e.to_string() })),
        )
            .into_response(),
    }
}

#[derive(serde::Deserialize)]
struct SetPreferenceBody {
    value: String,
}

#[utoipa::path(
    put,
    path = "/api/preferences/{key}",
    tag = "Preferences",
    summary = "Set a preference value",
    params(("key" = String, Path)),
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn set_preference(
    State(state): State<ServerState>,
    Path(key): Path<String>,
    Json(body): Json<SetPreferenceBody>,
) -> axum::response::Response {
    match state.preferences.set(&key, &body.value).await {
        Ok(()) => {
            if key == crate::privacy::PRODUCT_ANALYTICS_ENABLED_PREF_KEY {
                crate::ryu_analytics::set_product_analytics_from_value(&body.value);
                // The Ryu-owned local-Gateway relay gate is env-backed, so a
                // preference write needs one best-effort respawn to take effect.
                // A failed refresh never rolls back the persisted preference.
                if let Err(error) = state.gateway.refresh().await {
                    tracing::warn!(error = %error, "gateway: refresh after product-analytics change failed");
                }
            }
            if key == crate::exec_approval::EXEC_APPROVAL_MODE_PREF_KEY {
                crate::exec_approval::apply_from_pref(&body.value);
            }
            if key == conversations::ConversationStore::CHAT_MEMORY_ENABLED_PREF_KEY {
                let enabled =
                    conversations::ConversationStore::parse_chat_memory_enabled(Some(&body.value));
                if let Err(error) = state.conversations.set_chat_memory_enabled(enabled).await {
                    return (
                        StatusCode::INTERNAL_SERVER_ERROR,
                        Json(json!({ "error": error.to_string() })),
                    )
                        .into_response();
                }
                if enabled {
                    let conversations = state.conversations.clone();
                    tokio::spawn(async move {
                        if let Err(error) = conversations.reindex_message_embeddings().await {
                            tracing::warn!(
                                error = %error,
                                "chat memory: reindex after enabling failed"
                            );
                        }
                    });
                } else if let Err(error) = state.conversations.clear_message_embeddings().await {
                    return (
                        StatusCode::INTERNAL_SERVER_ERROR,
                        Json(json!({ "error": error.to_string() })),
                    )
                        .into_response();
                }
            }
            // Keep the in-process Hugging Face token resolver in sync so gated
            // model search + downloads pick up the change without a restart.
            if key == crate::hf_auth::HF_TOKEN_PREF_KEY {
                crate::hf_auth::set_token(&body.value);
            }
            // Same for the Artificial Analysis API key (model-catalog stats).
            if key == crate::model_catalog::aa::AA_API_KEY_PREF_KEY {
                crate::model_catalog::aa::set_key(&body.value).await;
            }
            // Managed-inference fleet coordinates. Re-read BOTH keys (the pair is
            // meaningless half-set — a URL with no token 401s against the fleet)
            // and refresh the process-global the synchronous `pi_config::apply`
            // path consults, so pointing a self-hosted node at managed inference
            // takes effect without a Core restart.
            if key == crate::sidecar::gateway::MANAGED_FLEET_URL_PREF_KEY
                || key == crate::sidecar::gateway::MANAGED_FLEET_TOKEN_PREF_KEY
            {
                let url = state
                    .preferences
                    .get(crate::sidecar::gateway::MANAGED_FLEET_URL_PREF_KEY)
                    .await
                    .ok()
                    .flatten();
                let token = state
                    .preferences
                    .get(crate::sidecar::gateway::MANAGED_FLEET_TOKEN_PREF_KEY)
                    .await
                    .ok()
                    .flatten();
                crate::sidecar::gateway::set_managed_fleet_pref(url, token);
            }
            // The node-routing envelope is read synchronously on every gateway
            // forward. Refresh its pre-encoded carrier after the atomic JSON
            // preference write so fallback/firewall edits apply immediately.
            if key == crate::sidecar::gateway::NODE_ROUTING_PREF_KEY {
                crate::sidecar::gateway::set_node_routing_prefs_from_json(&body.value);
            }
            // And the AA fetch mode (cached daily cache vs. realtime live fetch).
            if key == crate::model_catalog::aa::AA_MODE_PREF_KEY {
                crate::model_catalog::aa::set_mode(&body.value);
            }
            // Composio API key: keep the resolver in sync AND respawn the gateway
            // so its Composio tool loop picks up the new key (the gateway reads
            // `COMPOSIO_API_KEY` from its spawn env; a refresh re-injects it).
            // Best-effort — a refresh failure must not fail the preference write.
            if key == crate::composio_auth::COMPOSIO_API_KEY_PREF_KEY {
                crate::composio_auth::set_key(&body.value);
                if let Err(e) = state.gateway.refresh().await {
                    tracing::warn!("gateway: refresh after Composio key change failed: {e}");
                }
            }
            // OpenRouter API key (A4 / #501): same pattern — keep the resolver in
            // sync and respawn the gateway so its `openrouter` provider picks up
            // the new key (the gateway reads `OPENROUTER_API_KEY` from spawn env).
            if key == crate::openrouter_auth::OPENROUTER_API_KEY_PREF_KEY {
                crate::openrouter_auth::set_key(&body.value);
                if let Err(e) = state.gateway.refresh().await {
                    tracing::warn!("gateway: refresh after OpenRouter key change failed: {e}");
                }
            }
            // Cloud media provider keys (Replicate / Fal): same pattern — sync the
            // resolver and respawn the gateway so its `replicate` / `fal` media
            // providers pick up the new key (read from spawn env).
            if key == crate::replicate_auth::REPLICATE_API_KEY_PREF_KEY {
                crate::replicate_auth::set_key(&body.value);
                if let Err(e) = state.gateway.refresh().await {
                    tracing::warn!("gateway: refresh after Replicate key change failed: {e}");
                }
            }
            if key == crate::fal_auth::FAL_API_KEY_PREF_KEY {
                crate::fal_auth::set_key(&body.value);
                if let Err(e) = state.gateway.refresh().await {
                    tracing::warn!("gateway: refresh after Fal key change failed: {e}");
                }
            }
            // Claude Code gateway-routing toggle: keep the in-process flag in sync
            // so the next Claude Code spawn injects (or omits) `ANTHROPIC_BASE_URL`.
            // No gateway respawn needed — the flag is read on Core's spawn path.
            if key == crate::claude_config::CLAUDE_GATEWAY_ROUTING_PREF_KEY {
                crate::claude_config::set_enabled(&body.value);
            }
            // RTK per-agent auto-wrap (rtk Phase 2): keep the in-process flag
            // in sync and reconcile the agent's RTK PreToolUse hook. Spawned so the
            // (possibly process-launching) `rtk init` never blocks the pref write;
            // a no-op when rtk is not on PATH.
            if let Some(agent) = crate::rtk_config::WrapAgent::from_pref_key(&key) {
                crate::rtk_config::set_enabled(agent, &body.value);
                let enable = crate::rtk_config::is_enabled(agent);
                tokio::spawn(async move {
                    if let Err(e) = crate::rtk_config::configure(agent, enable).await {
                        tracing::warn!(error = %e, "rtk auto-wrap: reconfigure on pref change failed");
                    }
                });
            }
            // RTK exclude list: merge into rtk's config.toml so its hooks + the
            // `rtk.run` tool skip these commands. No-op when rtk is not installed.
            if key == crate::rtk_config::EXCLUDE_COMMANDS_PREF_KEY {
                if let Err(e) = crate::rtk_config::set_exclude_commands(&body.value) {
                    tracing::warn!(error = %e, "rtk auto-wrap: writing exclude_commands failed");
                }
            }
            // Untrusted-content wrapping toggle: keep the in-process flag in sync
            // so the next tool result wraps (or, on opt-out, does not) before it
            // re-enters the model. Read on Core's tool-result path.
            if key == crate::sidecar::untrusted::UNTRUSTED_WRAPPING_PREF_KEY {
                crate::sidecar::untrusted::set_enabled(&body.value);
            }
            // Node entitlement gate (#496): keep the in-process flag in sync so
            // the scheduler pauses (or resumes) autonomous automation the moment
            // the desktop pushes a new entitlement verdict. No gateway respawn —
            // the flag is read on Core's (sync) scheduler tick path.
            if key == crate::entitlement::ENTITLEMENT_ACTIVE_PREF_KEY {
                crate::entitlement::set_active(&body.value);
            }
            if key == crate::entitlement::MANAGED_INFERENCE_ENTITLED_PREF_KEY {
                crate::entitlement::set_managed_inference_entitled(&body.value);
            }
            // Generic per-agent gateway routing: keep the in-process map in sync so
            // the next spawn of any toggled agent injects (or omits) OPENAI_BASE_URL.
            // No gateway respawn needed — the map is read on Core's spawn path.
            if key == crate::agent_routing::AGENT_GATEWAY_ROUTING_PREF_KEY {
                crate::agent_routing::set_from_json(&body.value);
            }
            // Per-agent MCP tool bridge: keep the in-process map in sync so the
            // next ACP session for the changed agent is built with (or without)
            // Ryu's bridge. A SEPARATE key from the gateway-routing one above —
            // writing egress must never move the tool gate, and vice versa.
            if key == crate::agent_routing::AGENT_TOOL_BRIDGE_PREF_KEY {
                crate::agent_routing::set_bridge_from_json(&body.value);
            }
            // Per-agent Plane A model-routing overrides (spec §1): keep the
            // in-process map in sync so the next forwarded chat injects (or omits)
            // `ryu_smart_route` for the changed agent. No gateway respawn — the map
            // is read on Core's (async) chat-forward path.
            if key == crate::agent_routing::AGENT_SMART_ROUTE_PREF_KEY {
                crate::agent_routing::set_smart_routes_from_json(&body.value);
            }
            // Plane B agent-auto routing config (spec §2): keep the in-process
            // snapshot in sync so the next "auto" turn resolves with the new rules.
            if key == crate::agent_routing::AGENT_AUTO_ROUTING_PREF_KEY {
                crate::agent_routing::set_auto_config_from_json(&body.value);
            }
            // Keep both lane snapshots in step so interactive chat and plugin
            // model resolution see preference writes without a restart.
            if key == crate::agent_selection::GLOBAL_SELECTION_PREF
                || key == crate::agent_selection::LOCAL_SELECTION_PREF
            {
                crate::agent_selection::set_local_selection_from_json(&body.value);
            } else if key == crate::agent_selection::CLOUD_SELECTION_PREF {
                crate::agent_selection::set_cloud_selection_from_json(&body.value);
            }
            (StatusCode::OK, Json(json!({ "ok": true, "key": key }))).into_response()
        }
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": e.to_string() })),
        )
            .into_response(),
    }
}

// ── Safe Mode ────────────────────────────────────────────────────────────────

/// Read the node's Safe Mode state, why it is in that state, and what it is
/// holding back.
///
/// The counts are the point. A bare on/off switch tells a user nothing about
/// whether it did anything; "34 plugins, 12 skills and 5 MCP servers suppressed"
/// is a measurement they can act on. They are computed against the RAW records —
/// the masked read would report zero enabled plugins and the payload would say
/// safe mode is suppressing nothing, which is precisely backwards.
#[utoipa::path(
    get,
    path = "/api/safe-mode",
    tag = "Safe Mode",
    summary = "Safe Mode state and what it suppresses",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_safe_mode(State(state): State<ServerState>) -> axum::response::Response {
    let source = crate::safe_mode::source();
    let records = state.app_store.list_all_records().await.unwrap_or_default();
    let (kernel, suppressible): (Vec<_>, Vec<_>) = records
        .iter()
        .filter(|r| r.enabled)
        .partition(|r| crate::safe_mode::keeps_plugin_enabled(&r.id));
    let counts = crate::safe_mode::SuppressedCounts {
        plugins: suppressible.len(),
        kernel_plugins: kernel.len(),
        skills: state.skills.enabled().len(),
        mcp_servers: crate::sidecar::mcp::McpRegistry::user_configured_server_count(),
    };
    // The stored preference is reported separately from the effective state: an
    // env-forced node has `enabled = true` with the pref still false, and a UI
    // that bound its switch to the effective flag alone would show a control the
    // user cannot move.
    let pref = state
        .preferences
        .get(crate::safe_mode::SAFE_MODE_PREF_KEY)
        .await
        .ok()
        .flatten();
    (
        StatusCode::OK,
        Json(json!({
            "enabled": crate::safe_mode::is_active(),
            "source": source.as_str(),
            "user_clearable": source.is_user_clearable(),
            "preference_enabled": crate::safe_mode::parse_enabled(pref.as_deref()),
            "suppressed": counts,
        })),
    )
        .into_response()
}

#[derive(serde::Deserialize)]
struct SetSafeModeBody {
    enabled: bool,
}

/// Turn Safe Mode on or off for the NEXT boot.
///
/// Writes both persistence tiers — the preference (so every surface sees the flip
/// over the existing preferences stream) and the `~/.ryu/safe-mode` sentinel (so
/// the next boot is safe even if this process dies before it restarts, and so a
/// Core that cannot serve HTTP can still be brought up safe). Never touches the
/// plugin lifecycle table: safe mode is a read mask, and leaving it must restore
/// the user's apps exactly, with no bookkeeping to replay.
///
/// Returns `restart_required: true` always, and that is not a cop-out. Applying
/// live would leave every sidecar, MCP child and scheduler loop that already
/// spawned still running — the switch would report success while the CPU cost it
/// exists to remove kept being paid.
#[utoipa::path(
    put,
    path = "/api/safe-mode",
    tag = "Safe Mode",
    summary = "Enable or disable Safe Mode (applies on restart)",
    request_body = serde_json::Value,
    responses(
        (status = 200, description = "OK", body = serde_json::Value),
        (status = 409, description = "Forced on by RYU_SAFE_MODE"),
    )
)]
async fn set_safe_mode(
    State(state): State<ServerState>,
    Json(body): Json<SetSafeModeBody>,
) -> axum::response::Response {
    // An env-forced node cannot be talked out of safe mode by a preference write:
    // the env tier outranks both persisted tiers, so honouring this would produce
    // a switch that flips in the UI and changes nothing on reboot.
    if !body.enabled && crate::safe_mode::source() == crate::safe_mode::SafeModeSource::Env {
        return (
            StatusCode::CONFLICT,
            Json(json!({
                "error": format!(
                    "safe mode is forced on by {}; unset it and restart to leave safe mode",
                    crate::safe_mode::SAFE_MODE_ENV
                ),
                "source": "env",
            })),
        )
            .into_response();
    }
    if let Err(e) = crate::safe_mode::write_sentinel(body.enabled) {
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": format!("could not write the safe-mode sentinel: {e}") })),
        )
            .into_response();
    }
    let value = if body.enabled { "true" } else { "false" };
    if let Err(e) = state
        .preferences
        .set(crate::safe_mode::SAFE_MODE_PREF_KEY, value)
        .await
    {
        // The sentinel already landed, so the next boot is correct either way;
        // report the failure rather than pretending the fan-out happened.
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": format!("could not persist the safe-mode preference: {e}") })),
        )
            .into_response();
    }
    tracing::warn!(
        enabled = body.enabled,
        "safe mode {} for the next boot",
        if body.enabled { "ARMED" } else { "cleared" }
    );
    (
        StatusCode::OK,
        Json(json!({
            "ok": true,
            "enabled": body.enabled,
            "active_now": crate::safe_mode::is_active(),
            "restart_required": true,
        })),
    )
        .into_response()
}

// -- Capability bindings (the override-mutation API — Track A/B) ------------------

/// `GET /api/capabilities` — the read model behind the layer picker: every
/// capability any ENABLED plugin provides, its candidate providers, whether the
/// capability is *selectable* (many providers may be enabled and one is picked, the
/// engine-style UX) and which provider is bound right now.
///
/// Resolved over the ENABLED set, not the installed set, because that is the set the
/// binding registry's invariants are stated over and the set a call actually sees. A
/// capability whose provider is merely installed therefore reads as unbound, which is
/// the truth: nothing would serve a call to it.
#[utoipa::path(
    get,
    path = "/api/capabilities",
    tag = "Plugins",
    summary = "List capabilities, their providers, and the current selection",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn list_capabilities(State(state): State<ServerState>) -> axum::response::Response {
    let records = match state.app_store.list().await {
        Ok(r) => r,
        Err(e) => return json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    };
    let enabled_ids: std::collections::HashSet<String> = records
        .iter()
        .filter(|r| r.enabled)
        .map(|r| r.id.clone())
        .collect();
    // `known` is every manifest Core has, enabled or not. The read model needs both:
    // `enabled` decides what actually binds, `known` is what keeps a capability
    // whose providers are all disabled VISIBLE (with its candidates listed under
    // `available`) instead of vanishing from the response entirely.
    let (enabled, known): (
        Vec<crate::plugin_manifest::PluginManifest>,
        Vec<crate::plugin_manifest::PluginManifest>,
    ) = {
        let manifests = state.app_manifests.read().await;
        let known: Vec<_> = manifests.iter().cloned().collect();
        let enabled: Vec<_> = known
            .iter()
            .filter(|m| enabled_ids.contains(&m.id))
            .cloned()
            .collect();
        (enabled, known)
    };

    let json = state
        .preferences
        .get(crate::plugins::binding::BINDING_OVERRIDES_PREF_KEY)
        .await
        .ok()
        .flatten()
        .unwrap_or_else(|| "{}".to_owned());
    let cfg = crate::plugins::binding::config_from_overrides_json(&json);
    let capabilities = crate::plugins::binding::describe_capabilities(&enabled, &known, &cfg);

    // The stable verb ids the facade currently serves, so a picker can show what a
    // layer actually exposes rather than only which app is selected.
    let verbs: Vec<serde_json::Value> =
        crate::sidecar::mcp::capability_tools::resolve_verbs(&enabled, &cfg)
            .into_iter()
            .map(|r| {
                json!({
                    "id": r.verb.id,
                    "capability": r.verb.capability,
                    "provider": r.provider_id,
                    "target": r.binding.tool,
                })
            })
            .collect();

    (
        StatusCode::OK,
        Json(json!({ "capabilities": capabilities, "verbs": verbs })),
    )
        .into_response()
}

/// `GET /api/capabilities/bindings` — the user's capability→provider overrides
/// (the tie-breaker when 2+ enabled apps provide the same capability). Empty = the
/// zero-config auto-pick (single provider, or an explicit Ambiguous refusal).
#[utoipa::path(
    get,
    path = "/api/capabilities/bindings",
    tag = "Plugins",
    summary = "Get capability binding overrides",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_capability_bindings(State(state): State<ServerState>) -> axum::response::Response {
    let json = state
        .preferences
        .get(crate::plugins::binding::BINDING_OVERRIDES_PREF_KEY)
        .await
        .ok()
        .flatten()
        .unwrap_or_else(|| "{}".to_owned());
    let cfg = crate::plugins::binding::config_from_overrides_json(&json);
    (StatusCode::OK, Json(json!({ "overrides": cfg.overrides }))).into_response()
}

#[derive(serde::Deserialize)]
struct SetBindingsBody {
    /// `capability name → provider app-id`.
    #[serde(default)]
    overrides: std::collections::BTreeMap<String, String>,
}

/// `PUT /api/capabilities/bindings` — replace the override map. Validated against
/// the CURRENTLY ENABLED set before it is persisted or applied: an override that
/// would leave an enabled consumer unbound/ambiguous (e.g. naming a non-provider,
/// or a provider that is not enabled) is refused (409). On success it persists and
/// applies live via `set_active_config`, so the next capability resolution / enable
/// / disable uses it; already-lowered runtime edges refresh on the next
/// enable/disable of the affected plugins.
#[utoipa::path(
    put,
    path = "/api/capabilities/bindings",
    tag = "Plugins",
    summary = "Set capability binding overrides",
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn set_capability_bindings(
    State(state): State<ServerState>,
    Json(body): Json<SetBindingsBody>,
) -> axum::response::Response {
    use crate::plugins::binding;
    let new_cfg = binding::BindingConfig {
        overrides: body.overrides,
    };

    // Validate over the ENABLED set: no enabled consumer may become unbound/ambiguous.
    let records = match state.app_store.list().await {
        Ok(r) => r,
        Err(e) => return json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    };
    let enabled_ids: std::collections::HashSet<String> = records
        .iter()
        .filter(|r| r.enabled)
        .map(|r| r.id.clone())
        .collect();
    let enabled: Vec<crate::plugin_manifest::PluginManifest> = {
        let manifests = state.app_manifests.read().await;
        manifests
            .iter()
            .filter(|m| enabled_ids.contains(&m.id))
            .cloned()
            .collect()
    };
    if let Some((plugin, err)) = binding::first_binding_error(&enabled, &new_cfg) {
        return (
            StatusCode::CONFLICT,
            Json(json!({
                "error": err.to_string(),
                "plugin": plugin,
                "binding_error": err.code(),
            })),
        )
            .into_response();
    }

    // Persist + apply live.
    let json = binding::overrides_to_json(&new_cfg);
    if let Err(e) = state
        .preferences
        .set(binding::BINDING_OVERRIDES_PREF_KEY, &json)
        .await
    {
        return json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string());
    }
    binding::set_active_config(new_cfg.clone());
    (
        StatusCode::OK,
        Json(json!({ "ok": true, "overrides": new_cfg.overrides })),
    )
        .into_response()
}

// -- Email transport (BYO SMTP sink config) --------------------------------------

/// Non-secret transport config exchanged with the desktop SMTP card. The password
/// is write-only (`password`, never returned); `passwordSet` reports whether one
/// is stored so the card can show a "configured" state without revealing it.
#[derive(serde::Deserialize)]
struct EmailTransportBody {
    #[serde(default)]
    host: String,
    #[serde(default = "default_smtp_port")]
    port: u16,
    #[serde(default)]
    username: String,
    #[serde(default)]
    from: String,
    #[serde(default = "default_true_bool")]
    starttls: bool,
    /// Optional secret. When present + non-empty it is persisted; an omitted /
    /// empty value leaves the stored password untouched.
    #[serde(default)]
    password: Option<String>,
}

fn default_smtp_port() -> u16 {
    587
}

fn default_true_bool() -> bool {
    true
}

/// `GET /api/email/transport` - the current non-secret SMTP transport config plus
/// a `passwordSet` flag. Never returns the password.
#[utoipa::path(
    get,
    path = "/api/email/transport",
    tag = "Notifications",
    summary = "Get the SMTP transport config (never the password)",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_email_transport(State(_state): State<ServerState>) -> axum::response::Response {
    let prefs = ryu_email_send::current_transport_prefs();
    let password_set = crate::smtp_auth::password().is_some();
    let body = match prefs {
        Some(t) => json!({
            "host": t.host,
            "port": t.port,
            "username": t.username,
            "from": t.from,
            "starttls": t.starttls,
            "passwordSet": password_set,
        }),
        None => json!({
            "host": "",
            "port": default_smtp_port(),
            "username": "",
            "from": "",
            "starttls": true,
            "passwordSet": password_set,
        }),
    };
    (StatusCode::OK, Json(body)).into_response()
}

/// `PUT /api/email/transport` - persist the non-secret transport config (and,
/// when supplied, the password) and apply both to the in-process sink without a
/// restart.
#[utoipa::path(
    put,
    path = "/api/email/transport",
    tag = "Notifications",
    summary = "Set the SMTP transport config",
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn put_email_transport(
    State(state): State<ServerState>,
    Json(body): Json<EmailTransportBody>,
) -> axum::response::Response {
    let transport = ryu_email_send::TransportPrefs {
        host: body.host.clone(),
        port: body.port,
        username: body.username.clone(),
        from: body.from.clone(),
        starttls: body.starttls,
    };
    let json = match serde_json::to_string(&transport) {
        Ok(j) => j,
        Err(e) => {
            return (
                StatusCode::INTERNAL_SERVER_ERROR,
                Json(json!({ "error": e.to_string() })),
            )
                .into_response()
        }
    };
    if let Err(e) = state
        .preferences
        .set(ryu_email_send::SMTP_TRANSPORT_PREF_KEY, &json)
        .await
    {
        return (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": e.to_string() })),
        )
            .into_response();
    }
    ryu_email_send::set_transport(
        &body.host,
        body.port,
        &body.username,
        &body.from,
        body.starttls,
    );

    // Persist the password only when supplied + non-empty (a blank/omitted value
    // leaves the stored secret intact).
    if let Some(password) = body.password.as_deref() {
        if !password.trim().is_empty() {
            if let Err(e) = state
                .preferences
                .set(crate::smtp_auth::SMTP_PASSWORD_PREF_KEY, password)
                .await
            {
                return (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    Json(json!({ "error": e.to_string() })),
                )
                    .into_response();
            }
            crate::smtp_auth::set_password(password);
        }
    }

    (StatusCode::OK, Json(json!({ "ok": true }))).into_response()
}

/// Body for `POST /api/email/test`.
#[derive(serde::Deserialize)]
struct EmailTestBody {
    to: String,
}

/// `POST /api/email/test` - send a test email over the currently-configured
/// transport, surfacing any [`ryu_email_send::EmailError`] to the caller.
#[utoipa::path(
    post,
    path = "/api/email/test",
    tag = "Notifications",
    summary = "Send a test email through the configured transport",
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn post_email_test(
    State(_state): State<ServerState>,
    Json(body): Json<EmailTestBody>,
) -> axum::response::Response {
    let Some(cfg) = ryu_email_send::resolve_transport() else {
        return (
            StatusCode::BAD_REQUEST,
            Json(json!({ "error": "email transport is not configured" })),
        )
            .into_response();
    };
    match ryu_email_send::send_email_alert(
        &cfg,
        body.to.trim(),
        "Ryu test email",
        "This is a test email from your Ryu node. Your SMTP transport is working.",
    )
    .await
    {
        Ok(id) => (StatusCode::OK, Json(json!({ "ok": true, "messageId": id }))).into_response(),
        Err(e) => (
            StatusCode::BAD_GATEWAY,
            Json(json!({ "ok": false, "error": e.to_string() })),
        )
            .into_response(),
    }
}

// -- Alert delivery targets (node-level policy-alert recipients) ------------------

/// Node-level alert delivery targets for self-host policy alerts. `targets` are
/// the Fanout-tier channels (webhook / Telegram / Expo push); `emails` are the
/// Email-tier recipients (sent over the shared BYO SMTP transport).
#[derive(serde::Deserialize)]
struct AlertDeliveryBody {
    #[serde(default)]
    targets: Vec<ryu_notify::NotifyTarget>,
    #[serde(default)]
    emails: Vec<String>,
}

/// `GET /api/alerts/delivery` - the node's configured policy-alert delivery
/// targets (empty default when unset).
#[utoipa::path(
    get,
    path = "/api/alerts/delivery",
    tag = "Notifications",
    summary = "Get the node's policy-alert delivery targets",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_alert_delivery(State(state): State<ServerState>) -> axum::response::Response {
    let Some(store) = crate::notify::global_store() else {
        return (
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({ "error": "notify store not ready" })),
        )
            .into_response();
    };
    let _ = &state;
    match store.get_alert_delivery().await {
        Ok(cfg) => (StatusCode::OK, Json(json!(cfg))).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": e.to_string() })),
        )
            .into_response(),
    }
}

/// `PUT /api/alerts/delivery` - persist the node's policy-alert delivery targets.
#[utoipa::path(
    put,
    path = "/api/alerts/delivery",
    tag = "Notifications",
    summary = "Set the node's policy-alert delivery targets",
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn put_alert_delivery(
    State(state): State<ServerState>,
    Json(body): Json<AlertDeliveryBody>,
) -> axum::response::Response {
    let Some(store) = crate::notify::global_store() else {
        return (
            StatusCode::SERVICE_UNAVAILABLE,
            Json(json!({ "error": "notify store not ready" })),
        )
            .into_response();
    };
    let _ = &state;
    let cfg = crate::policy_alerts::AlertDeliveryTargets {
        targets: body.targets,
        emails: body.emails,
    };
    match store.set_alert_delivery(&cfg).await {
        Ok(()) => (StatusCode::OK, Json(json!({ "ok": true }))).into_response(),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "error": e.to_string() })),
        )
            .into_response(),
    }
}

// ── Per-model launch config (advanced inference) ───────────────────────────────

