/// `GET /api/spaces/:id/documents` — the Space's documents, each **file** row
/// carrying its content-extraction state under `index`.
///
/// The `index` object is `FileIndexRecord::to_json` — byte-identical to what the
/// create responses and `…/documents/:doc_id/index` return, so a client needs one
/// reader for all three. It is attached **only** to `kind = 'file'` rows: a page,
/// database or whiteboard is re-chunked from its own source on every save, so the
/// question does not apply to it and answering anyway would be a fresh overclaim.
///
/// Joined in one pass ([`crate::space_file_index::attach_index_states`]) rather than
/// left to the client. It is a two-store join — the rows come from `ryu-spaces`, the
/// state from Core's own `space-file-index.db` — and the desktop was paying one HTTP
/// request per file row to render a searchability badge, against a Space (Uploads)
/// whose length is bounded by nothing.
///
/// The join runs **after** `caller_doc_filter`, so state is attached only to rows
/// this caller was already permitted to see; it adds no ACL of its own because the
/// list's own filter is the check.
#[utoipa::path(
    get,
    path = "/api/spaces/{id}/documents",
    tag = "Spaces",
    summary = "List documents in a space",
    params(("id" = String, Path)),
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn list_documents(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    axum::extract::Path(id): axum::extract::Path<String>,
) -> axum::response::Response {
    if enforce_permission_on(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_READ,
        crate::acl::KIND_SPACE,
        &id,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.read".to_owned(),
        );
    }
    match state
        .spaces
        .list_documents(&id, caller_doc_filter(&caller))
        .await
    {
        Ok(documents) => {
            // Serialize first, then decorate: `spaces::Document` has no index field
            // and must not grow one (the crate has zero dependency on `apps/core`,
            // which is what keeps parser provenance out of its schema). A failure to
            // serialize the rows is not survivable, but it is also not a reason to
            // lose the list — fall back to the undecorated payload.
            let mut rows = match serde_json::to_value(&documents) {
                Ok(serde_json::Value::Array(rows)) => rows,
                other => {
                    tracing::warn!("list_documents: unexpected document encoding: {other:?}");
                    return Json(json!({ "space_id": id, "documents": documents })).into_response();
                }
            };
            crate::space_file_index::attach_index_states(&mut rows).await;
            Json(json!({ "space_id": id, "documents": rows })).into_response()
        }
        Err(e) => json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    }
}

#[derive(serde::Deserialize)]
struct SearchSpacesQuery {
    q: String,
    limit: Option<usize>,
}

/// `GET /api/spaces/search` — literal global search over visible Space metadata
/// and document text. This is intentionally separate from per-Space RAG search:
/// the palette needs fast, predictable lexical recall and must still work when no
/// embedding model is available.
#[utoipa::path(
    get,
    path = "/api/spaces/search",
    tag = "Spaces",
    summary = "Search visible spaces and pages lexically",
    params(
        ("q" = String, Query, description = "Text to find"),
        ("limit" = Option<usize>, Query, description = "Maximum number of page hits")
    ),
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn search_space_documents(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    axum::extract::Query(query): axum::extract::Query<SearchSpacesQuery>,
) -> axum::response::Response {
    if enforce_permission(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_READ,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.read".to_owned(),
        );
    }
    let text = query.q.trim();
    if text.len() < 2 {
        return Json(json!({ "hits": [], "indexed": true })).into_response();
    }
    let limit = query.limit.unwrap_or(8).clamp(1, 50);
    match state
        .spaces
        .search_documents_lexical(text, limit, caller_doc_filter(&caller))
        .await
    {
        Ok(hits) => Json(json!({ "hits": hits, "indexed": true })).into_response(),
        Err(e) => json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    }
}

/// The seeded system-space NAME an app's documents live in. There is no server-side
/// app→space link yet — the association is the space NAME, seeded at boot in
/// `main.rs` (`ensure_system_space("Canvas"/"Whiteboard"/…)`), so the mapping lives
/// here. An app not in this map has no document space (its section shows nothing).
fn app_space_name(plugin_id: &str) -> Option<&'static str> {
    match plugin_id {
        "@ryu/canvas" => Some("Canvas"),
        "@ryu/whiteboard" => Some("Whiteboard"),
        _ => None,
    }
}

/// `GET /api/apps/:id/docs` — an app's documents (kind `app:<id>`, isolated by
/// `app_list_docs`) in its seeded Space, shaped for a sidebar section's declarative
/// `source`: `{ documents: [{ id, title, space_id, updated_at }] }`.
async fn list_app_docs(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    axum::extract::Path(plugin_id): axum::extract::Path<String>,
) -> axum::response::Response {
    if enforce_permission(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_READ,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.read".to_owned(),
        );
    }
    let Some(space_name) = app_space_name(&plugin_id) else {
        return Json(json!({ "documents": [] })).into_response();
    };
    let space_id = match state.spaces.ensure_system_space(space_name, None).await {
        Ok(id) => id,
        Err(e) => return json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    };
    match state.spaces.app_list_docs(&plugin_id, &space_id).await {
        Ok(docs) => {
            let documents: Vec<serde_json::Value> = docs
                .iter()
                .map(|d| {
                    json!({
                        "id": d.id,
                        "title": d.title,
                        "space_id": space_id,
                        "updated_at": d.updated_at,
                    })
                })
                .collect();
            Json(json!({ "documents": documents })).into_response()
        }
        Err(e) => json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    }
}

#[derive(serde::Deserialize)]
struct CreateAppDocBody {
    #[serde(default)]
    title: Option<String>,
}

/// `POST /api/apps/:id/docs` (`{ title? }`) — create a doc of kind `app:<id>` in the
/// app's Space and return `{ id, space_id }`, so a section's "+" can create-and-open.
async fn create_app_doc(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    axum::extract::Path(plugin_id): axum::extract::Path<String>,
    Json(body): Json<CreateAppDocBody>,
) -> axum::response::Response {
    if enforce_permission(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_WRITE,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.write".to_owned(),
        );
    }
    let Some(space_name) = app_space_name(&plugin_id) else {
        return json_error(
            StatusCode::BAD_REQUEST,
            format!("no document space for app: {plugin_id}"),
        );
    };
    let space_id = match state.spaces.ensure_system_space(space_name, None).await {
        Ok(id) => id,
        Err(e) => return json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    };
    let title = body
        .title
        .filter(|t| !t.trim().is_empty())
        .unwrap_or_else(|| "Untitled".to_owned());
    match state
        .spaces
        .app_create_doc(
            &plugin_id,
            &space_id,
            &title,
            &crate::server::spaces::background_owner(),
        )
        .await
    {
        Ok(id) => Json(json!({ "id": id, "space_id": space_id })).into_response(),
        Err(e) => json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    }
}

#[derive(serde::Deserialize)]
struct IngestBody {
    title: String,
    content: String,
}

#[utoipa::path(
    post,
    path = "/api/spaces/{id}/documents",
    tag = "Spaces",
    summary = "Ingest a document into a space",
    params(("id" = String, Path)),
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn ingest_document(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    axum::extract::Path(id): axum::extract::Path<String>,
    Json(body): Json<IngestBody>,
) -> axum::response::Response {
    if enforce_permission_on(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_WRITE,
        crate::acl::KIND_SPACE,
        &id,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.write".to_owned(),
        );
    }
    if let Err(resp) = require_resource_write(
        spaces::space_access_meta(&state.spaces, &id).await,
        caller.as_ref(),
        "space not found",
    ) {
        return resp;
    }
    match state
        .spaces
        .ingest_document(
            &id,
            body.title.trim(),
            &body.content,
            &spaces::owner_of(&caller_tenancy(&caller)),
        )
        .await
    {
        Ok(document_id) => Json(json!({ "document_id": document_id })).into_response(),
        Err(e) => {
            let msg = e.to_string();
            let status = if msg.contains("not found") {
                StatusCode::NOT_FOUND
            } else {
                StatusCode::INTERNAL_SERVER_ERROR
            };
            json_error(status, msg)
        }
    }
}

#[derive(serde::Deserialize)]
struct SearchBody {
    query: String,
    #[serde(default = "default_search_limit")]
    limit: usize,
    /// Override wiki link-expansion for this search (`None` = server default,
    /// governed by `RYU_SPACES_LINK_EXPANSION`).
    #[serde(default)]
    link_expansion: Option<bool>,
}

fn default_search_limit() -> usize {
    5
}

#[utoipa::path(
    post,
    path = "/api/spaces/{id}/search",
    tag = "Spaces",
    summary = "Search a space (RAG)",
    params(("id" = String, Path)),
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn search_space(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    axum::extract::Path(id): axum::extract::Path<String>,
    Json(body): Json<SearchBody>,
) -> axum::response::Response {
    // Coarse RBAC: searching a space requires `space.read` (this also denies a
    // tokenless caller on a bound node). The per-resource tenancy filter below then
    // ensures the returned chunks only come from documents THIS caller may read.
    if enforce_permission_on(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_READ,
        crate::acl::KIND_SPACE,
        &id,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.read".to_owned(),
        );
    }
    if let Err(response) = require_resource_read(
        spaces::space_access_meta(&state.spaces, &id).await,
        caller.as_ref(),
        "space not found",
    ) {
        return response;
    }
    let limit = body.limit.clamp(1, 50);
    // Lazily start the (off-by-default) reranker server so Spaces RAG can neural-
    // rerank. Fire-and-forget: the current search fails open to the vector order
    // if the server isn't warm yet; subsequent searches rerank once it is up.
    {
        let manager = state.manager.clone();
        tokio::spawn(async move {
            if let Err(e) = manager.start_sidecar("llamacpp-rerank").await {
                tracing::debug!("llamacpp-rerank lazy start skipped: {e:#}");
            }
        });
    }
    match state
        .spaces
        .search_ext(
            &id,
            &body.query,
            limit,
            body.link_expansion,
            caller_doc_filter(&caller),
        )
        .await
    {
        Ok(matches) => Json(json!({ "space_id": id, "matches": matches })).into_response(),
        Err(e) => json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    }
}

