/// Max decoded size for a single uploaded file artifact. Bounds memory on the create
/// path; larger assets should stream via a future chunked upload.
///
/// **Defined as [`uploads::MAX_UPLOAD_BYTES`] (32 MiB), not as a number of its own.**
/// It used to read `200 * 1024 * 1024`, and that figure was wrong twice: the route is
/// reached through a base64 JSON body, so the ceiling a client could actually hit was
/// ~1.5 MiB (axum's implicit 2 MiB body limit, no explicit layer, minus the 4/3
/// expansion) — and 200 MiB was nonetheless what the desktop settings panel printed as
/// "Maximum file in a Space". See [`uploads::SPACE_FILE_BODY_LIMIT`] for the alignment
/// and why the fix went down to 32 MiB rather than up to 200.
const MAX_FILE_BYTES: usize = uploads::MAX_UPLOAD_BYTES;

#[derive(serde::Deserialize)]
struct CreateFileBody {
    title: String,
    /// MIME type of the file (e.g. `application/pdf`, `image/png`).
    #[serde(default)]
    mime: Option<String>,
    /// Standard base64-encoded file bytes.
    data_base64: String,
}

#[derive(serde::Deserialize)]
struct ReplaceFileBody {
    /// MIME type of the replacement file. Omitted values retain the stored MIME.
    #[serde(default)]
    mime: Option<String>,
    /// Standard base64-encoded file bytes.
    data_base64: String,
}

fn decode_space_file_body(data_base64: &str) -> Result<Vec<u8>, axum::response::Response> {
    use base64::Engine as _;
    if uploads::decoded_len_lower_bound(data_base64.len()) > MAX_FILE_BYTES {
        return Err(json_error(
            StatusCode::PAYLOAD_TOO_LARGE,
            uploads::SPACE_FILE_BODY_LIMIT
                .too_large_message(uploads::Observed::BodyBytes(data_base64.len())),
        ));
    }
    let bytes = base64::engine::general_purpose::STANDARD
        .decode(data_base64.as_bytes())
        .map_err(|e| json_error(StatusCode::BAD_REQUEST, format!("invalid base64: {e}")))?;
    if bytes.len() > MAX_FILE_BYTES {
        return Err(json_error(
            StatusCode::PAYLOAD_TOO_LARGE,
            uploads::SPACE_FILE_BODY_LIMIT
                .too_large_message(uploads::Observed::FileBytes(bytes.len())),
        ));
    }
    Ok(bytes)
}

/// `POST /api/spaces/:id/files` — store a binary file as a first-class Space
/// document (`kind = 'file'`). The bytes go to the content-addressed blob store;
/// the row carries the mime + sha + size. This is the substrate the
/// `create_artifact` tool and chat auto-filing of generated pptx/xlsx/csv/pdf/png
/// build on. Writing requires `space.write` (org/team RBAC) — the same governed
/// gate every external-agent write flows through.
#[utoipa::path(
    post,
    path = "/api/spaces/{id}/files",
    tag = "Spaces",
    summary = "Store a binary file document",
    params(("id" = String, Path)),
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn create_file(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    axum::extract::Path(id): axum::extract::Path<String>,
    Json(body): Json<CreateFileBody>,
) -> axum::response::Response {
    if enforce_permission_on(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_WRITE,
        crate::acl::KIND_SPACE,
        &id,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.write".to_owned(),
        );
    }
    if let Err(resp) = require_space_content_write(&state, &caller, &id, "space not found").await {
        return resp;
    }
    let title = if body.title.trim().is_empty() {
        "Untitled"
    } else {
        body.title.trim()
    };
    let mime = body
        .mime
        .as_deref()
        .map(str::trim)
        .filter(|m| !m.is_empty())
        .unwrap_or("application/octet-stream");
    // Refuse from the ENCODED length first, so an oversize upload is rejected without
    // ever allocating the decode buffer it was trying to make us allocate. The LOWER
    // bound is the right one to test: it cannot refuse a file that would have fit (see
    // `decoded_len_lower_bound` — the upper bound rejects a file of exactly the limit),
    // and the exact check below still enforces the boundary.
    let bytes = match decode_space_file_body(&body.data_base64) {
        Ok(bytes) => bytes,
        Err(response) => return response,
    };
    // Shared ingest path (see [`crate::space_file_index`]): the bytes are stored AND
    // their text is extracted through the `document.parse` facade, so the document is
    // retrievable by its contents rather than only by its filename. Extraction can
    // never fail this call — `index` carries what happened to it.
    match crate::space_file_index::create_file_indexed(
        &state,
        &id,
        title,
        &bytes,
        mime,
        &spaces::owner_of(&caller_tenancy(&caller)),
    )
    .await
    {
        Ok(created) => Json(json!({
            "id": created.document_id,
            "mime": mime,
            "byte_size": bytes.len(),
            "index": created.index.to_json(),
        }))
        .into_response(),
        Err(e) => {
            let msg = e.to_string();
            let status = if msg.contains("not found") {
                StatusCode::NOT_FOUND
            } else {
                StatusCode::INTERNAL_SERVER_ERROR
            };
            json_error(status, msg)
        }
    }
}

/// `PUT /api/spaces/:id/documents/:doc_id/blob` — replace the bytes of an
/// existing file document and re-index the saved revision. The document's real
/// parent Space and its own ACL are authoritative; the URL Space id is never used
/// to grant access.
#[utoipa::path(
    put,
    path = "/api/spaces/{id}/documents/{doc_id}/blob",
    tag = "Spaces",
    summary = "Replace a file document's bytes",
    params(("id" = String, Path), ("doc_id" = String, Path)),
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn replace_file_blob(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    axum::extract::Path((_url_space_id, doc_id)): axum::extract::Path<(String, String)>,
    Json(body): Json<ReplaceFileBody>,
) -> axum::response::Response {
    let Some(owning_space) = document_parent_space(&state, &doc_id).await else {
        return json_error(StatusCode::NOT_FOUND, "file not found".to_owned());
    };
    if enforce_permission_on(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_WRITE,
        crate::acl::KIND_SPACE,
        &owning_space,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.write".to_owned(),
        );
    }
    if let Err(response) = require_resource_write(
        spaces::doc_access_meta(&state.spaces, &doc_id).await,
        caller.as_ref(),
        "file not found",
    ) {
        return response;
    }
    let current = match state.spaces.get_file_meta(&doc_id).await {
        Ok(Some(meta)) => meta,
        Ok(None) => return json_error(StatusCode::NOT_FOUND, "file not found".to_owned()),
        Err(error) => {
            return json_error(StatusCode::INTERNAL_SERVER_ERROR, error.to_string());
        }
    };
    let mime = body
        .mime
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .unwrap_or(&current.mime);
    let bytes = match decode_space_file_body(&body.data_base64) {
        Ok(bytes) => bytes,
        Err(response) => return response,
    };
    match crate::space_file_index::replace_file_indexed(&state, &doc_id, &bytes, mime).await {
        Ok(updated) => Json(json!({
            "id": updated.document_id,
            "mime": mime,
            "byte_size": bytes.len(),
            "index": updated.index.to_json(),
        }))
        .into_response(),
        Err(error) => {
            let message = error.to_string();
            let status = if message.contains("not found") {
                StatusCode::NOT_FOUND
            } else {
                StatusCode::INTERNAL_SERVER_ERROR
            };
            json_error(status, message)
        }
    }
}

/// `GET /api/spaces/:id/documents/:doc_id/blob` — stream a file document's bytes
/// with its stored MIME type. Reading requires `space.read`.
#[utoipa::path(
    get,
    path = "/api/spaces/{id}/documents/{doc_id}/blob",
    tag = "Spaces",
    summary = "Download a file document's bytes",
    params(("id" = String, Path), ("doc_id" = String, Path)),
    responses((status = 200, description = "OK"))
)]
async fn get_file_blob(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    // `_url_space_id` is deliberately unused: it is caller-supplied and the gate
    // below resolves the document's REAL parent instead.
    axum::extract::Path((_url_space_id, doc_id)): axum::extract::Path<(String, String)>,
) -> axum::response::Response {
    // Resolve the TRUE parent space; the URL id is caller-supplied.
    let Some(owning_space) = document_parent_space(&state, &doc_id).await else {
        return json_error(StatusCode::NOT_FOUND, "document not found".to_owned());
    };
    if enforce_permission_on(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_READ,
        crate::acl::KIND_SPACE,
        &owning_space,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.read".to_owned(),
        );
    }
    // Per-resource ACL: a file document's BYTES are its content — gate on the row,
    // not just on the coarse `space.read` permission.
    if let Err(resp) = require_resource_read(
        spaces::doc_access_meta(&state.spaces, &doc_id).await,
        caller.as_ref(),
        "file not found",
    ) {
        return resp;
    }
    match state.spaces.read_file_blob(&doc_id).await {
        Ok(Some((mime, bytes))) => {
            use axum::http::header;
            // Stored-XSS defense: a blob's stored Content-Type is caller-controlled,
            // so an uploaded `text/html` / `image/svg+xml` would otherwise render
            // in-origin. Force safe delivery — normalize risky renderable MIME types
            // to octet-stream, force download (`Content-Disposition: attachment`),
            // forbid MIME sniffing, and sandbox via CSP so even a mis-typed blob
            // cannot execute script in the app origin.
            (
                StatusCode::OK,
                [
                    (header::CONTENT_TYPE, normalize_blob_mime(&mime)),
                    (header::CONTENT_DISPOSITION, "attachment".to_owned()),
                    (header::X_CONTENT_TYPE_OPTIONS, "nosniff".to_owned()),
                    (
                        header::CONTENT_SECURITY_POLICY,
                        "sandbox; default-src 'none'".to_owned(),
                    ),
                ],
                bytes,
            )
                .into_response()
        }
        Ok(None) => json_error(StatusCode::NOT_FOUND, "file not found".to_owned()),
        Err(e) => json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    }
}

/// Normalize a stored blob's caller-controlled MIME type for safe HTTP delivery.
///
/// Renderable, script-capable types (HTML, XHTML, SVG, any `*+xml`, bare XML) and
/// an empty/absent type are collapsed to `application/octet-stream` so the browser
/// never parses them as active content in the app origin. Everything else (images,
/// audio, PDF, plain data) passes through unchanged — the `Content-Disposition:
/// attachment` + `nosniff` + CSP `sandbox` headers on the response are the primary
/// guarantee; this normalization is defense in depth.
fn normalize_blob_mime(mime: &str) -> String {
    let base = mime
        .split(';')
        .next()
        .unwrap_or("")
        .trim()
        .to_ascii_lowercase();
    let risky = matches!(
        base.as_str(),
        "text/html" | "application/xhtml+xml" | "image/svg+xml" | "application/xml" | "text/xml"
    ) || base.ends_with("+xml")
        || base.is_empty();
    if risky {
        "application/octet-stream".to_owned()
    } else {
        mime.to_owned()
    }
}

#[cfg(test)]
mod blob_mime_tests {
    use super::normalize_blob_mime;

    #[test]
    fn risky_types_are_neutralized() {
        for m in [
            "text/html",
            "text/html; charset=utf-8",
            "image/svg+xml",
            "application/xhtml+xml",
            "application/atom+xml",
            "application/xml",
            "TEXT/HTML",
            "",
            "   ",
        ] {
            assert_eq!(
                normalize_blob_mime(m),
                "application/octet-stream",
                "'{m}' should be neutralized"
            );
        }
    }

    #[test]
    fn safe_types_pass_through() {
        for m in ["image/png", "application/pdf", "audio/mpeg", "text/plain"] {
            assert_eq!(normalize_blob_mime(m), m, "'{m}' should pass through");
        }
    }
}

/// `GET /api/spaces/:id/documents/:doc_id` — fetch a document's markdown source.
#[utoipa::path(
    get,
    path = "/api/spaces/{id}/documents/{doc_id}",
    tag = "Spaces",
    summary = "Get a document",
    params(("id" = String, Path), ("doc_id" = String, Path)),
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_document(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    // `_url_space_id` is deliberately unused: it is caller-supplied and the gate
    // below resolves the document's REAL parent instead.
    axum::extract::Path((_url_space_id, doc_id)): axum::extract::Path<(String, String)>,
) -> axum::response::Response {
    // Org/team RBAC (coarse): reading a document requires `space.read`.
    // Resolve the TRUE parent space; the URL id is caller-supplied.
    let Some(owning_space) = document_parent_space(&state, &doc_id).await else {
        return json_error(StatusCode::NOT_FOUND, "document not found".to_owned());
    };
    if enforce_permission_on(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_READ,
        crate::acl::KIND_SPACE,
        &owning_space,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.read".to_owned(),
        );
    }
    // Per-resource ACL (fine): `space.read` says the caller may read documents at
    // all; this says they may read THIS one. Without it, any org member holding
    // `space.read` could read another member's PRIVATE document.
    if let Err(resp) = require_resource_read(
        spaces::doc_access_meta(&state.spaces, &doc_id).await,
        caller.as_ref(),
        "document not found",
    ) {
        return resp;
    }
    match state.spaces.get_document(&doc_id).await {
        Ok(Some(doc)) => Json(doc).into_response(),
        Ok(None) => json_error(StatusCode::NOT_FOUND, "document not found".to_owned()),
        Err(e) => json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    }
}

#[derive(serde::Deserialize)]
struct UpdateDocumentBody {
    title: String,
    source: String,
    #[serde(default)]
    expected_revision: Option<i64>,
    #[serde(default)]
    operation_id: Option<String>,
}

/// `PUT /api/spaces/:id/documents/:doc_id` — save edits (re-embeds on save).
#[utoipa::path(
    put,
    path = "/api/spaces/{id}/documents/{doc_id}",
    tag = "Spaces",
    summary = "Update a document",
    params(("id" = String, Path), ("doc_id" = String, Path)),
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn update_document(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    // `_url_space_id` is deliberately unused: it is caller-supplied and the gate
    // below resolves the document's REAL parent instead.
    axum::extract::Path((_url_space_id, doc_id)): axum::extract::Path<(String, String)>,
    Json(body): Json<UpdateDocumentBody>,
) -> axum::response::Response {
    if body
        .operation_id
        .as_deref()
        .is_some_and(|operation_id| operation_id.is_empty() || operation_id.len() > 128)
    {
        return json_error(
            StatusCode::BAD_REQUEST,
            "operation_id must contain between 1 and 128 bytes".to_owned(),
        );
    }
    // Resolve the TRUE parent space; the URL id is caller-supplied.
    let Some(owning_space) = document_parent_space(&state, &doc_id).await else {
        return json_error(StatusCode::NOT_FOUND, "document not found".to_owned());
    };
    if enforce_permission_on(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_WRITE,
        crate::acl::KIND_SPACE,
        &owning_space,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.write".to_owned(),
        );
    }
    // Per-resource ACL: a write needs `Access::Write` on THIS document, so an org
    // Viewer (read-only) and a non-owner on a private doc are both refused.
    if let Err(resp) = require_resource_write(
        spaces::doc_access_meta(&state.spaces, &doc_id).await,
        caller.as_ref(),
        "document not found",
    ) {
        return resp;
    }
    match state
        .spaces
        .update_document_versioned(
            &doc_id,
            body.title.trim(),
            &body.source,
            body.expected_revision,
            body.operation_id.as_deref(),
            caller.as_ref().map(|value| value.user_id.as_str()),
        )
        .await
    {
        Ok(spaces::DocumentUpdateOutcome::Applied(result)) => {
            Json(json!({ "success": true, "result": result })).into_response()
        }
        Ok(spaces::DocumentUpdateOutcome::Conflict { current_revision }) => (
            StatusCode::CONFLICT,
            Json(json!({
                "error": "document revision conflict",
                "current_revision": current_revision,
            })),
        )
            .into_response(),
        Err(e) => {
            let msg = e.to_string();
            let status = if msg.contains("not found") {
                StatusCode::NOT_FOUND
            } else {
                StatusCode::INTERNAL_SERVER_ERROR
            };
            json_error(status, msg)
        }
    }
}

#[derive(serde::Deserialize)]
struct SetDocumentAccessBody {
    /// `private`, `org`, or `team`.
    visibility: String,
    /// Required when `visibility` is `team`; cleared for the other modes.
    #[serde(default)]
    team_id: Option<String>,
}

/// `PUT /api/spaces/:id/documents/:doc_id/access` — change native document
/// visibility. This is separate from generic ACL overwrites: it controls the
/// document's owner/org/team tenancy row and therefore also drives list/search
/// filtering.
#[utoipa::path(
    put,
    path = "/api/spaces/{id}/documents/{doc_id}/access",
    tag = "Spaces",
    summary = "Set document visibility",
    params(("id" = String, Path), ("doc_id" = String, Path)),
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn set_document_access(
    State(state): State<ServerState>,
    axum::Extension(caller): axum::Extension<Option<crate::identity_verify::VerifiedCaller>>,
    axum::extract::Path((_url_space_id, doc_id)): axum::extract::Path<(String, String)>,
    Json(body): Json<SetDocumentAccessBody>,
) -> axum::response::Response {
    let Some(owning_space) = document_parent_space(&state, &doc_id).await else {
        return json_error(StatusCode::NOT_FOUND, "document not found".to_owned());
    };
    if enforce_permission_on(
        &state,
        &caller,
        crate::identity_verify::permissions::SPACE_WRITE,
        crate::acl::KIND_SPACE,
        &owning_space,
    )
    .await
    .is_err()
    {
        return json_error(
            StatusCode::FORBIDDEN,
            "insufficient permissions: space.write".to_owned(),
        );
    }
    if let Err(resp) = require_resource_write(
        spaces::doc_access_meta(&state.spaces, &doc_id).await,
        caller.as_ref(),
        "document not found",
    ) {
        return resp;
    }

    let visibility = body.visibility.trim().to_ascii_lowercase();
    if !matches!(visibility.as_str(), "private" | "org" | "team") {
        return json_error(
            StatusCode::BAD_REQUEST,
            "visibility must be \"private\", \"org\", or \"team\"".to_owned(),
        );
    }
    let team_id = body
        .team_id
        .as_deref()
        .map(str::trim)
        .filter(|id| !id.is_empty());
    if visibility == "team" && team_id.is_none() {
        return json_error(
            StatusCode::BAD_REQUEST,
            "team visibility requires team_id".to_owned(),
        );
    }
    match state
        .spaces
        .set_document_access(&doc_id, &visibility, team_id)
        .await
    {
        Ok(true) => Json(json!({
            "success": true,
            "visibility": visibility,
            "team_id": team_id,
        }))
        .into_response(),
        Ok(false) => json_error(StatusCode::NOT_FOUND, "document not found".to_owned()),
        Err(e) => json_error(StatusCode::INTERNAL_SERVER_ERROR, e.to_string()),
    }
}

