/// Body for `POST /workflows/runs/:run_id/resume`.
#[derive(serde::Deserialize, Default)]
struct ResumeWorkflowBody {
    /// Value to inject as the suspended Awakeable gate's output. Becomes the
    /// input to downstream nodes. Defaults to empty string when absent.
    #[serde(default)]
    payload: String,
}

/// `POST /workflows/runs/:run_id/resume` — resume a run suspended at an
/// Awakeable gate.
///
/// Acceptance criteria:
/// - 404 when the run does not exist.
/// - 409 when the run is not in `awaiting_input` status.
/// - Completes the Awakeable gate with the caller-supplied `payload`, persists,
///   re-invokes the executor (which skips all already-Completed nodes and
///   continues from the gate's successor), and returns the final run state.
#[utoipa::path(
    post,
    path = "/workflows/runs/{run_id}/resume",
    tag = "Workflows",
    summary = "Resume a workflow run (HITL)",
    params(("run_id" = String, Path)),
    request_body = serde_json::Value,
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn resume_workflow_run(
    axum::extract::Path(run_id): axum::extract::Path<String>,
    body: Option<Json<ResumeWorkflowBody>>,
) -> (StatusCode, Json<serde_json::Value>) {
    let body = body.map(|b| b.0).unwrap_or_default();

    // Delegate to the reusable resume core (shared with the approval engine, so a
    // manual resume and an approved workflow-gate resume are identical). Map its
    // error string onto the right status code.
    match crate::workflow::resume_run(&run_id, body.payload).await {
        Ok(completed_run) => (
            StatusCode::OK,
            Json(json!({ "success": true, "run": completed_run })),
        ),
        Err(e) => {
            let status = if e.contains("not found") {
                StatusCode::NOT_FOUND
            } else if e.contains("not awaiting input") {
                StatusCode::CONFLICT
            } else {
                StatusCode::INTERNAL_SERVER_ERROR
            };
            (status, Json(json!({ "success": false, "error": e })))
        }
    }
}

// ── Sub-agent delegation ──────────────────────────────────────────────────────

/// Body for `POST /api/delegate/stream`: a parent hands one or more tasks to
/// sub-agents that run with a clean context under a permission preset and caps.
#[derive(serde::Deserialize, Default)]
struct DelegateBody {
    /// The sibling delegates to fan out (run concurrently, bounded by caps).
    #[serde(default)]
    delegates: Vec<crate::workflow::delegation::DelegateSpec>,
    /// Parent conversation to list completed subagent children under.
    #[serde(default)]
    conversation_id: Option<String>,
    /// Optional caps override; concurrency is clamped to the hard maximum.
    #[serde(default)]
    caps: Option<crate::workflow::delegation::DelegationCaps>,
    /// Depth of these delegates (a top-level parent delegating is depth 1).
    #[serde(default = "default_delegate_depth")]
    depth: usize,
}

fn default_delegate_depth() -> usize {
    1
}

/// `POST /api/delegate/stream` — run a delegation fan-out and stream progress.
///
/// Each delegate's `started`/`finished` event is emitted as an SSE line as it
/// happens, so the client sees same-depth delegates progress concurrently. A
/// terminal `done` event carries the ordered result array.
#[utoipa::path(
    post,
    path = "/api/delegate/stream",
    tag = "Chat",
    summary = "Stream a sub-agent delegation (SSE)",
    request_body = serde_json::Value,
    responses((status = 200, description = "Server-Sent Events stream"))
)]
async fn delegate_stream(
    State(state): State<ServerState>,
    body: Option<Json<DelegateBody>>,
) -> axum::response::Response {
    use crate::sidecar::adapters::sse_response;
    use crate::workflow::delegation;

    let body = body.map(|b| b.0).unwrap_or_default();
    let caps = body.caps.unwrap_or_default();
    let depth = body.depth;
    let parent_conversation_id = body.conversation_id.filter(|s| !s.is_empty());
    let delegates = body.delegates;
    let delegates_for_persist = delegates.clone();
    let conversations = state.conversations.clone();

    let (tx, mut rx) = tokio::sync::mpsc::unbounded_channel::<delegation::DelegateProgress>();

    // Spawn the fan-out; progress events arrive on `rx` while it runs.
    let fanout =
        tokio::spawn(async move { delegation::run_fanout(delegates, caps, depth, Some(tx)).await });

    let stream = async_stream::stream! {
        while let Some(ev) = rx.recv().await {
            let line = match serde_json::to_string(&ev) {
                Ok(json) => format!("data: {json}\n\n"),
                Err(_) => continue,
            };
            yield Ok::<_, std::convert::Infallible>(line.into_bytes());
        }

        let terminal = match fanout.await {
            Ok(Ok(results)) => {
                if !results.is_empty() {
                    let completed = results.iter().filter(|result| result.error.is_none()).count();
                    let failed = results.len() - completed;
                    crate::events::publish_system_notification(
                        if failed == 0 {
                            "Other agents finished"
                        } else {
                            "Other agents finished with issues"
                        },
                        format!("{completed} of {} delegated tasks completed.", results.len()),
                        if failed == 0 { "success" } else { "warning" },
                    );
                }
                if let Some(parent_id) = parent_conversation_id.as_deref() {
                    persist_delegate_children(
                        &conversations,
                        parent_id,
                        &delegates_for_persist,
                        &results,
                    )
                    .await;
                }
                json!({ "event": "done", "results": results })
            },
            Ok(Err(e)) => json!({ "event": "error", "error": e.to_string() }),
            Err(e) => json!({ "event": "error", "error": format!("delegation task failed: {e}") }),
        };
        yield Ok::<_, std::convert::Infallible>(
            format!("data: {terminal}\n\n").into_bytes(),
        );
    };

    sse_response(axum::body::Body::from_stream(stream))
}

async fn persist_delegate_children(
    conversations: &ConversationStore,
    parent_conversation_id: &str,
    delegates: &[crate::workflow::delegation::DelegateSpec],
    results: &[crate::workflow::delegation::DelegateResult],
) {
    let specs_by_id: std::collections::HashMap<&str, &crate::workflow::delegation::DelegateSpec> =
        delegates
            .iter()
            .map(|spec| (spec.id.as_str(), spec))
            .collect();
    for result in results {
        let Some(spec) = specs_by_id.get(result.id.as_str()) else {
            continue;
        };
        let answer = result
            .output
            .as_deref()
            .or(result.error.as_deref())
            .unwrap_or("");
        let preset = serde_json::to_value(result.preset)
            .ok()
            .and_then(|value| value.as_str().map(str::to_owned));
        if let Err(e) = conversations
            .append_subagent_child(
                parent_conversation_id,
                &spec.task,
                answer,
                spec.agent_id.as_deref(),
                preset.as_deref(),
                result.child_conversation_id.as_deref(),
            )
            .await
        {
            tracing::warn!("failed to persist subagent child entry: {e:#}");
        }
    }
}

// ── Scheduled-job handlers (heartbeat) ──────────────────────────────────────

#[utoipa::path(
    get,
    path = "/heartbeat/jobs",
    tag = "Core",
    summary = "List the scheduled jobs",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn list_jobs() -> Json<serde_json::Value> {
    let jobs = crate::scheduler::store::list_jobs();
    Json(json!({ "jobs": jobs }))
}

#[derive(serde::Deserialize)]
struct CreateJobBody {
    name: String,
    schedule: crate::scheduler::store::Schedule,
    target: crate::scheduler::store::JobTarget,
    #[serde(default = "default_enabled")]
    enabled: bool,
    /// When true, each due firing waits for a human-in-the-loop approval before
    /// running (raises an inbox request). Off by default.
    #[serde(default)]
    require_approval: bool,
    /// Manifest id of the App creating this job, when one is. Recorded so the
    /// tick loop can stop the job while its App is disabled — see
    /// [`crate::scheduler::store::ScheduledJob::owner_app`].
    #[serde(default)]
    owner_app: Option<String>,
}

fn default_enabled() -> bool {
    true
}

async fn create_job(
    State(state): State<ServerState>,
    Json(body): Json<CreateJobBody>,
) -> (StatusCode, Json<serde_json::Value>) {
    if let crate::scheduler::store::JobTarget::Agent { agent_id, .. } = &body.target {
        match state.agent_store.get(agent_id).await {
            Ok(Some(agent))
                if agent.lifecycle_status != crate::agents::AgentLifecycleStatus::Active =>
            {
                if body.enabled {
                    return (
                        StatusCode::BAD_REQUEST,
                        Json(json!({
                            "success": false,
                            "error": format!("agent '{}' is in {} mode and cannot have an enabled automation", agent.name, agent.lifecycle_status.as_str())
                        })),
                    );
                }
            }
            Ok(Some(_)) => {}
            Ok(None) => {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(
                        json!({ "success": false, "error": format!("agent '{agent_id}' not found") }),
                    ),
                );
            }
            Err(error) => {
                return (
                    StatusCode::INTERNAL_SERVER_ERROR,
                    Json(json!({ "success": false, "error": error.to_string() })),
                );
            }
        }
    }

    // Validate the schedule up front so a broken cron is never persisted.
    if let crate::scheduler::store::Schedule::Cron { expr, tz } = &body.schedule {
        if let Err(e) = crate::scheduler::cron::CronSchedule::parse(expr) {
            return (
                StatusCode::BAD_REQUEST,
                Json(json!({ "success": false, "error": e })),
            );
        }
        // Reject an unknown zone here rather than at tick time: a job that
        // parses but never fires is the worst outcome for a schedule, because
        // nothing reports it.
        if let Some(name) = tz {
            if let Err(e) = crate::scheduler::cron::parse_tz(name) {
                return (
                    StatusCode::BAD_REQUEST,
                    Json(json!({ "success": false, "error": e })),
                );
            }
        }
    }
    if let crate::scheduler::store::Schedule::Every { interval } = &body.schedule {
        if humantime::parse_duration(interval).is_err() {
            return (
                StatusCode::BAD_REQUEST,
                Json(
                    json!({ "success": false, "error": format!("invalid interval '{interval}'") }),
                ),
            );
        }
    }

    let now = chrono::Utc::now().to_rfc3339();
    let job = crate::scheduler::store::ScheduledJob {
        id: format!("job_{}", uuid::Uuid::new_v4().simple()),
        name: body.name,
        schedule: body.schedule,
        target: body.target,
        enabled: body.enabled,
        require_approval: body.require_approval,
        owner_app: body.owner_app.filter(|s| !s.trim().is_empty()),
        created_at: now.clone(),
        updated_at: now,
        last_run_at: None,
        last_outcome: None,
        history: Vec::new(),
    };

    match crate::scheduler::store::save_job(&job) {
        Ok(()) => (StatusCode::OK, Json(json!({ "success": true, "job": job }))),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "success": false, "error": e.to_string() })),
        ),
    }
}

#[utoipa::path(
    get,
    path = "/heartbeat/jobs/{id}",
    tag = "Core",
    summary = "Get one scheduled job",
    params(("id" = String, Path)),
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_job(
    axum::extract::Path(id): axum::extract::Path<String>,
) -> (StatusCode, Json<serde_json::Value>) {
    match crate::scheduler::store::load_job(&id) {
        Ok(job) => (StatusCode::OK, Json(json!({ "job": job }))),
        Err(_) => (
            StatusCode::NOT_FOUND,
            Json(json!({ "success": false, "error": "job not found" })),
        ),
    }
}

async fn delete_job(
    axum::extract::Path(id): axum::extract::Path<String>,
) -> (StatusCode, Json<serde_json::Value>) {
    match crate::scheduler::store::delete_job(&id) {
        Ok(true) => (StatusCode::OK, Json(json!({ "success": true }))),
        Ok(false) => (
            StatusCode::NOT_FOUND,
            Json(json!({ "success": false, "error": "job not found" })),
        ),
        Err(e) => (
            StatusCode::INTERNAL_SERVER_ERROR,
            Json(json!({ "success": false, "error": e.to_string() })),
        ),
    }
}

/// Validate a portable agent schedule with the same rules as the public job
/// endpoint. Templates must never be able to write a job that the scheduler
/// would silently skip after import.
fn validate_agent_schedule(schedule: &crate::scheduler::store::Schedule) -> Result<(), String> {
    match schedule {
        crate::scheduler::store::Schedule::Cron { expr, tz } => {
            crate::scheduler::cron::CronSchedule::parse(expr).map_err(|error| error.to_string())?;
            if let Some(name) = tz {
                crate::scheduler::cron::parse_tz(name).map_err(|error| error.to_string())?;
            }
        }
        crate::scheduler::store::Schedule::Every { interval } => {
            humantime::parse_duration(interval)
                .map_err(|_| format!("invalid interval '{interval}'"))?;
        }
    }
    Ok(())
}

fn validate_agent_schedules(
    schedules: &[crate::agents::AgentScheduleTemplate],
) -> Result<(), String> {
    for (index, schedule) in schedules.iter().enumerate() {
        validate_agent_schedule(&schedule.schedule)
            .map_err(|error| format!("schedule {}: {error}", index + 1))?;
        if schedule.instructions.trim().is_empty() {
            return Err(format!(
                "schedule {}: custom instructions are required",
                index + 1
            ));
        }
    }
    Ok(())
}

fn build_agent_schedule_jobs(
    agent_id: &str,
    agent_name: &str,
    schedules: &[crate::agents::AgentScheduleTemplate],
) -> Result<Vec<crate::scheduler::store::ScheduledJob>, String> {
    validate_agent_schedules(schedules)?;
    let now = chrono::Utc::now().to_rfc3339();
    schedules
        .iter()
        .enumerate()
        .map(|(index, schedule)| {
            let name = if schedule.name.trim().is_empty() {
                format!("{agent_name} schedule {}", index + 1)
            } else {
                schedule.name.trim().to_owned()
            };
            Ok(crate::scheduler::store::ScheduledJob {
                id: format!("job_{}", uuid::Uuid::new_v4().simple()),
                name,
                schedule: schedule.schedule.clone(),
                target: crate::scheduler::store::JobTarget::Agent {
                    agent_id: agent_id.to_owned(),
                    prompt: schedule.instructions.trim().to_owned(),
                    model: None,
                },
                enabled: schedule.enabled,
                require_approval: schedule.require_approval,
                owner_app: None,
                created_at: now.clone(),
                updated_at: now.clone(),
                last_run_at: None,
                last_outcome: None,
                history: Vec::new(),
            })
        })
        .collect()
}

/// Materialize portable schedules only after the agent exists. If one file
/// cannot be written, remove the files written by this operation so a partial
/// import cannot leave a misleading half-configured agent behind.
fn persist_agent_schedules(
    agent_id: &str,
    agent_name: &str,
    schedules: &[crate::agents::AgentScheduleTemplate],
) -> Result<(), String> {
    let jobs = build_agent_schedule_jobs(agent_id, agent_name, schedules)?;
    let mut saved_ids: Vec<String> = Vec::new();
    for job in jobs {
        if let Err(error) = crate::scheduler::store::save_job(&job) {
            for id in saved_ids {
                let _ = crate::scheduler::store::delete_job(&id);
            }
            return Err(error.to_string());
        }
        saved_ids.push(job.id);
    }
    Ok(())
}

fn agent_schedule_templates(agent_id: &str) -> Vec<crate::agents::AgentScheduleTemplate> {
    crate::scheduler::store::list_jobs()
        .into_iter()
        .filter_map(|job| {
            let crate::scheduler::store::JobTarget::Agent {
                agent_id: target_agent_id,
                prompt,
                ..
            } = job.target
            else {
                return None;
            };
            if target_agent_id != agent_id {
                return None;
            }
            Some(crate::agents::AgentScheduleTemplate {
                name: job.name,
                schedule: job.schedule,
                instructions: prompt,
                enabled: job.enabled,
                require_approval: job.require_approval,
            })
        })
        .collect()
}

fn delete_agent_schedules(agent_id: &str) -> std::io::Result<()> {
    for job in crate::scheduler::store::list_jobs() {
        let is_agent_job = matches!(
            &job.target,
            crate::scheduler::store::JobTarget::Agent { agent_id: target_id, .. }
                if target_id == agent_id
        );
        if is_agent_job {
            crate::scheduler::store::delete_job(&job.id)?;
        }
    }
    Ok(())
}

/// Keep automation definitions so promotion can restore the operator's intent,
/// but make every owned job inert as soon as an agent leaves `active`.
fn disable_agent_schedules(agent_id: &str) -> std::io::Result<()> {
    for mut job in crate::scheduler::store::list_jobs() {
        let is_agent_job = matches!(
            &job.target,
            crate::scheduler::store::JobTarget::Agent { agent_id: target_id, .. }
                if target_id == agent_id
        );
        let is_workflow_job = matches!(
            &job.target,
            crate::scheduler::store::JobTarget::Workflow { workflow_id, .. }
                if crate::workflow::store::load_workflow(workflow_id)
                    .ok()
                    .map(|workflow| {
                        crate::workflow::referenced_agent_ids(&workflow)
                            .iter()
                            .any(|referenced| referenced == agent_id)
                    })
                    .unwrap_or(false)
        );
        if (is_agent_job || is_workflow_job) && job.enabled {
            job.enabled = false;
            job.updated_at = chrono::Utc::now().to_rfc3339();
            crate::scheduler::store::save_job(&job)?;
        }
    }
    Ok(())
}

/// `POST /heartbeat/jobs/:id/run` — run a scheduled job now, off-schedule.
///
/// The "does this actually work" affordance every automation surface wants, and
/// the only honest one: it runs the *saved* job through the same
/// [`crate::scheduler::run_target`] the tick loop uses, so what it proves is what
/// will happen when the schedule fires — not an approximation assembled by the
/// caller. The outcome is recorded in the job's history exactly as a scheduled
/// run is, which is why a manual run shows up alongside the automatic ones.
///
/// Deliberately ignores `enabled` and `require_approval`: this IS the human
/// acting, so gating it on a schedule flag or on an approval the same human
/// would immediately grant would only be ceremony. It respects nothing about
/// *when* the job would have run, only *what* it runs.
#[utoipa::path(
    post,
    path = "/heartbeat/jobs/{id}/run",
    tag = "Core",
    summary = "Run a scheduled job now",
    params(("id" = String, Path)),
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn run_job_now(
    axum::extract::Path(id): axum::extract::Path<String>,
) -> (StatusCode, Json<serde_json::Value>) {
    let Ok(mut job) = crate::scheduler::store::load_job(&id) else {
        return (
            StatusCode::NOT_FOUND,
            Json(json!({ "success": false, "error": "job not found" })),
        );
    };

    let started_at = chrono::Utc::now().to_rfc3339();
    let result = crate::scheduler::run_target(&job.target).await;
    let finished_at = chrono::Utc::now().to_rfc3339();

    let (record, response) = match result {
        Ok(run_id) => (
            crate::scheduler::store::ExecRecord {
                started_at,
                finished_at,
                outcome: crate::scheduler::store::ExecOutcome::Success,
                run_id: run_id.clone(),
                error: None,
            },
            (
                StatusCode::OK,
                Json(json!({ "success": true, "run_id": run_id })),
            ),
        ),
        Err(error) => (
            crate::scheduler::store::ExecRecord {
                started_at,
                finished_at,
                outcome: crate::scheduler::store::ExecOutcome::Failure,
                run_id: None,
                error: Some(error.clone()),
            },
            // 200 with `success: false`, not a 5xx: the request was served
            // correctly and the *job* failed. The caller renders the message.
            (
                StatusCode::OK,
                Json(json!({ "success": false, "error": error })),
            ),
        ),
    };

    job.record_execution(record);
    if let Err(e) = crate::scheduler::store::save_job(&job) {
        tracing::error!("failed to persist job '{}' after a manual run: {e}", job.id);
    }
    response
}

#[utoipa::path(
    get,
    path = "/api/setup/check/{name}",
    tag = "Sidecars",
    summary = "Check whether a sidecar is installed",
    params(("name" = String, Path)),
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn check_installed(
    State(state): State<ServerState>,
    axum::extract::Path(name): axum::extract::Path<String>,
) -> Json<serde_json::Value> {
    use crate::sidecar::download_manager::VersionStore;

    let in_session = state.setup.is_installed(&name).await;
    let in_store = VersionStore::load().versions.contains_key(&name);

    let installed = (in_session || in_store) && binary_installed_on_disk(&name);

    Json(json!({ "name": name, "installed": installed }))
}

#[utoipa::path(
    get,
    path = "/api/setup/status",
    tag = "Sidecars",
    summary = "Install status for all sidecars",
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_install_status(State(state): State<ServerState>) -> Json<serde_json::Value> {
    use crate::sidecar::download_manager::VersionStore;
    use crate::sidecar::install_state::InstallState;

    // The in-memory InstallStatusStore only knows about installs/uninstalls that
    // happened in *this* core session. To report per-engine state for *every*
    // installed engine (including ones installed in a previous session, e.g.
    // both llama.cpp and ollama side by side), hydrate from the durable
    // versions.json and verify each binary still exists on disk.
    let mut states = state.install_status.get_all().await;

    let store = VersionStore::load();
    for (name, version) in &store.versions {
        // Don't override a live session state (Installing / Failed / freshly
        // Installed) — that is always the most accurate.
        if states.contains_key(name) {
            continue;
        }
        if binary_installed_on_disk(name) {
            states.insert(
                name.clone(),
                InstallState::Installed {
                    version: version.clone(),
                    installed_at: chrono::Utc::now(),
                },
            );
        }
    }

    Json(json!({ "states": states }))
}

#[utoipa::path(
    get,
    path = "/api/setup/status/{name}",
    tag = "Sidecars",
    summary = "Install status for one sidecar",
    params(("name" = String, Path)),
    responses((status = 200, description = "OK", body = serde_json::Value))
)]
async fn get_install_status_by_name(
    State(state): State<ServerState>,
    axum::extract::Path(name): axum::extract::Path<String>,
) -> Json<serde_json::Value> {
    use crate::sidecar::download_manager::VersionStore;
    use crate::sidecar::install_state::InstallState;

    // Prefer the live session state; otherwise fall back to the durable store so
    // an engine installed in a previous session still reports as installed.
    let status = match state.install_status.get(&name).await {
        InstallState::NotInstalled => match VersionStore::load().versions.get(&name) {
            Some(version) if binary_installed_on_disk(&name) => InstallState::Installed {
                version: version.clone(),
                installed_at: chrono::Utc::now(),
            },
            _ => InstallState::NotInstalled,
        },
        live => live,
    };
    Json(json!({ "name": name, "status": status }))
}

fn command_exists(program: &str) -> bool {
    Command::new(program)
        .arg("--version")
        .no_window()
        .output()
        .map(|output| output.status.success())
        .unwrap_or(false)
}

fn dependency_status() -> (serde_json::Map<String, serde_json::Value>, bool) {
    let git_installed = command_exists("git");
    let rust_installed = command_exists("rustc");
    let npm_installed = command_exists("npm") || command_exists("bun");
    let python_installed = command_exists("python3") || command_exists("python");
    let all_installed = git_installed && rust_installed && npm_installed && python_installed;

    let mut dependencies = serde_json::Map::new();
    dependencies.insert("git".to_string(), json!(git_installed));
    dependencies.insert("rust".to_string(), json!(rust_installed));
    dependencies.insert("npm".to_string(), json!(npm_installed));
    dependencies.insert("python".to_string(), json!(python_installed));

    (dependencies, all_installed)
}

fn run_install_command(program: &str, args: &[&str]) -> Result<(), String> {
    let output = Command::new(program)
        .args(args)
        .no_window()
        .output()
        .map_err(|error| format!("{program} failed to start: {error}"))?;

    if output.status.success() {
        return Ok(());
    }

    let stderr = String::from_utf8_lossy(&output.stderr).trim().to_string();
    let status = output.status.code().map_or_else(
        || "terminated by signal".to_string(),
        |code| code.to_string(),
    );

    if stderr.is_empty() {
        Err(format!("{program} exited with status {status}"))
    } else {
        Err(format!("{program} exited with status {status}: {stderr}"))
    }
}

fn run_first_success(commands: &[(&str, &[&str])]) -> Result<(), String> {
    let mut errors = Vec::new();
    for (program, args) in commands {
        match run_install_command(program, args) {
            Ok(()) => return Ok(()),
            Err(error) => errors.push(error),
        }
    }
    Err(errors.join("; "))
}

fn install_git() -> Result<(), String> {
    #[cfg(target_os = "windows")]
    {
        run_install_command(
            "winget",
            &[
                "install",
                "--id",
                "Git.Git",
                "-e",
                "--accept-source-agreements",
                "--accept-package-agreements",
            ],
        )
    }

    #[cfg(target_os = "macos")]
    {
        run_install_command("brew", &["install", "git"])
    }

    #[cfg(target_os = "linux")]
    {
        run_first_success(&[
            ("sudo", &["apt-get", "install", "-y", "git"][..]),
            ("sudo", &["dnf", "install", "-y", "git"][..]),
            ("sudo", &["yum", "install", "-y", "git"][..]),
        ])
    }

    #[cfg(not(any(target_os = "windows", target_os = "macos", target_os = "linux")))]
    {
        Err("automatic git install is unsupported on this platform".to_string())
    }
}

